-- J5: best hit per protein to each model organism (YEAST, NEUCR, SCHPO, EMENI) from swissprot_hits, chunked by species_prefix range.
CREATE OR REPLACE TABLE model_subj AS SELECT sp_id, org_code, accession, entry_name, s_len FROM '{T}/swissprot_subject.parquet' WHERE org_code IN ('YEAST','NEUCR','SCHPO','EMENI');
-- @output A9/anchor_chunks/anchor_0.parquet
COPY (SELECT h.protein_id, h.species_prefix AS genome, m.org_code, m.sp_id AS anchor_sp_id, m.accession AS anchor_acc, m.s_len AS anchor_len, h.rk, h.pident_x10, h.qcov_x10, h.scov_x10, h.q_len, h.bitscore FROM read_parquet('{T}/swissprot_hits/*.parquet') h JOIN model_subj m USING (sp_id) WHERE h.species_prefix >= 'F0' AND h.species_prefix < 'F1' QUALIFY row_number() OVER (PARTITION BY h.protein_id, m.org_code ORDER BY h.bitscore DESC, h.rk) = 1) TO '{OUT}' (FORMAT PARQUET, COMPRESSION ZSTD);
-- @output A9/anchor_chunks/anchor_1.parquet
COPY (SELECT h.protein_id, h.species_prefix AS genome, m.org_code, m.sp_id AS anchor_sp_id, m.accession AS anchor_acc, m.s_len AS anchor_len, h.rk, h.pident_x10, h.qcov_x10, h.scov_x10, h.q_len, h.bitscore FROM read_parquet('{T}/swissprot_hits/*.parquet') h JOIN model_subj m USING (sp_id) WHERE h.species_prefix >= 'F1' AND h.species_prefix < 'F2' QUALIFY row_number() OVER (PARTITION BY h.protein_id, m.org_code ORDER BY h.bitscore DESC, h.rk) = 1) TO '{OUT}' (FORMAT PARQUET, COMPRESSION ZSTD);
