-- @output A9/protein_model_anchor.parquet
COPY (SELECT * FROM read_parquet('{A}/A9/anchor_chunks/anchor_*.parquet') ORDER BY genome, protein_id) TO '{OUT}' (FORMAT PARQUET, COMPRESSION ZSTD, ROW_GROUP_SIZE 500000);
-- @output A4/fam_anchor_genome.parquet
-- Model-anchor families (P-B): per (org_code, anchor_sp_id, representative genome); strict gates on the anchor hit; complete models via protein_core.
COPY (SELECT a.org_code, a.anchor_sp_id, a.genome, any_value(a.anchor_len) AS anchor_len, count(*) AS n_prot_all, median(c.length) AS med_len_all, count(*) FILTER (WHERE c.q_model) AS n_prot_model, median(c.length) FILTER (WHERE c.q_model) AS med_len_model FROM '{A}/A9/protein_model_anchor.parquet' a JOIN '{A}/A3/protein_core.parquet' c USING (protein_id) JOIN '{A}/labels/genome_labels.parquet' l ON a.genome = l.LOCUSTAG WHERE l.is_representative AND a.qcov_x10 >= 800 AND a.scov_x10 >= 800 AND a.pident_x10 >= 400 GROUP BY 1,2,3 ORDER BY 1,2,3) TO '{OUT}' (FORMAT PARQUET, COMPRESSION ZSTD);
-- @output A9/anchor_genome_summary.parquet
COPY (SELECT genome, org_code, count(*) AS n_anchored, count(*) FILTER (WHERE qcov_x10 >= 800 AND scov_x10 >= 800 AND pident_x10 >= 400) AS n_strict FROM '{A}/A9/protein_model_anchor.parquet' GROUP BY 1,2 ORDER BY 1,2) TO '{OUT}' (FORMAT PARQUET, COMPRESSION ZSTD);
